package org.nbscn.varvis.variantanalysis.provider;
import static org.junit.jupiter.api.Assertions.*;
import static org.nbscn.varvis.variantanalysis.provider.Bs4TestMaterials.*;
import static org.nbscn.varvis.variantanalysis.provider.Bs4NonSegregationCriterionEvaluatorTest.minimal;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import java.util.*;
class Bs4NonSegregationMatrixTest {
 static void issue(ObjectNode root)throws Exception {reissue(root,PARTS.toArray(String[]::new));}
 static void synchronizeDetection(ObjectNode root){var o=observation(root);for(var review:o.at("/nonSegregationReview/memberReviews"))for(var rec:o.at("/facts/records"))if(review.path("memberId").equals(rec.path("memberId")))obj(review,"/negativeTest").set("result",rec.at("/observation/call"));}
 @ParameterizedTest @ValueSource(strings={"memberId","sourcePersonId","sampleId","recordId","locator"})
 void nfcDuplicate(String field)throws Exception{var r=base("alpha-2");boolean record=field.equals("recordId")||field.equals("locator");var rows=observation(r).at(record?"/facts/records":"/facts/members");((ObjectNode)rows.get(0)).put(field,"TEST_é");((ObjectNode)rows.get(1)).put(field,"TEST_e\u0301");issue(r);minimal(evaluate(r),record?"BS4_RECORD_MEMBERSHIP_OR_DUPLICATE":"BS4_MEMBERS_NOT_DISTINCT");}
 @ParameterizedTest @ValueSource(strings={"0/1","1/0","0|1","1|0"})
 void legalHeterozygote(String gt)throws Exception{var r=base("beta-3");for(var rec:observation(r).at("/facts/records"))if(rec.at("/observation/call").asText().equals("HET_ALT"))call((ObjectNode)rec,gt);issue(r);assertEquals(-4,evaluate(r).path("appliedPoints").asInt());}
 @Test void legalReferencePhased()throws Exception{var r=base("alpha-3");for(var rec:observation(r).at("/facts/records"))if(rec.at("/observation/call").asText().equals("HOM_REF"))call((ObjectNode)rec,"0|0");issue(r);assertEquals(-4,evaluate(r).path("appliedPoints").asInt());}
 @ParameterizedTest @ValueSource(strings={"no-event","proband-reference","homozygous-alt","both-parents-het","unaffected-carrier"})
 void genotypeClinicalBoundaries(String kind)throws Exception{var r=base("alpha-3");var o=observation(r);String expected="CHILD_GENOTYPE_CLINICAL_CONFLICT";
  if(kind.equals("no-event")){for(int i=3;i<5;i++)call(obj(o,"/facts/records/"+i),"0/1");obj(o,"/nonSegregationReview").putArray("declaredNonSegregatingMembers");expected="NONSEGREGATION_NOT_ESTABLISHED";}
  else if(kind.equals("proband-reference")){call(obj(o,"/facts/records/2"),"0/0");expected="CHILD_GENOTYPE_CLINICAL_CONFLICT";}
  else if(kind.equals("both-parents-het")){call(obj(o,"/facts/records/0"),"0/1");expected="PARENT_GENOTYPE_CLINICAL_CONFLICT";}
  else if(kind.equals("homozygous-alt"))call(obj(o,"/facts/records/3"),"1/1");
  else {var member=obj(o,"/facts/members/3");member.put("affectedStatus","UNAFFECTED");obj(member,"/clinical").put("diagnosis","UNAFFECTED_CONFIRMED");call(obj(o,"/facts/records/3"),"0/1");dropAffectedReview(o,member.path("memberId").asText());}
  synchronizeDetection(r);issue(r);minimal(evaluate(r),"BS4_"+expected);
 }
 static void dropAffectedReview(ObjectNode o,String id){var d=obj(o,"/diseaseApplicability");for(String field:List.of("affectedMembers","alternativeExplanations")){var a=(ArrayNode)d.path(field);for(int i=a.size()-1;i>=0;i--)if(a.get(i).path("memberId").asText().equals(id))a.remove(i);}}
 @Test void healthyReferenceAndCarrierBackgroundNeverAddsWeight()throws Exception{var r=base("alpha-5");var o=observation(r);call(obj(o,"/facts/records/4"),"0/1");var healthy=obj(o,"/facts/members/5");healthy.put("affectedStatus","UNAFFECTED");obj(healthy,"/clinical").put("diagnosis","UNAFFECTED_CONFIRMED");dropAffectedReview(o,healthy.path("memberId").asText());var declared=obj(o,"/nonSegregationReview").putArray("declaredNonSegregatingMembers");declared.add(o.at("/facts/members/3/memberId")).add(o.at("/facts/members/6/memberId"));synchronizeDetection(r);issue(r);var result=evaluate(r);assertEquals(-4,result.path("appliedPoints").asInt());assertEquals(2,result.path("eventCount").asInt());assertEquals(5,result.path("nonSegregationEvents").size());}
 @Test void oneBadSiblingInvalidatesWholeBundle()throws Exception{for(String kind:List.of("clinical","source","quality")){var r=base("alpha-3");var o=observation(r);String reason;
  if(kind.equals("clinical")){obj(o,"/facts/members/4").put("affectedStatus","UNKNOWN");reason="CLINICAL_STATUS_UNESTABLISHED";}
  else if(kind.equals("source")){obj(o,"/facts/members/4/detection").putArray("sourceIds").add("wrong-source");reason="SOURCE_REFERENCE_UNRESOLVED";}
  else {obj(o,"/facts/records/4").put("rawSample","0/0:40:10:40,0:PASS");reason="RECORD_QUALITY_UNSUPPORTED";}issue(r);minimal(evaluate(r),"BS4_"+reason);}}
 @Test void sourceRosterCannotBeClipped()throws Exception{var r=base("alpha-3");((ArrayNode)observation(r).at("/facts/members")).remove(4);pinsOnly(r);minimal(evaluate(r),"BS4_SOURCE_FACTS_MISMATCH");}
 @Test void independentlyReissuedFactsStillNeedCompleteReview()throws Exception{var r=base("alpha-3");var f=obj(observation(r),"/facts");((ArrayNode)f.path("members")).remove(4);((ArrayNode)f.path("records")).remove(4);var parentage=(ArrayNode)f.path("parentage");parentage.remove(5);parentage.remove(4);reissue(r,"facts");minimal(evaluate(r),"BS4_ROSTER_REVIEW_MISMATCH");}
 @Test void familyCardinalityAndMultipleObservations()throws Exception{var r=base("alpha-5");var a=(ArrayNode)observation(r).at("/facts/members");a.add(((ObjectNode)a.get(6)).deepCopy().put("memberId","sixth").put("sampleId","sixth-sample").put("sourcePersonId","sixth-person"));issue(r);minimal(evaluate(r),"BS4_NUCLEAR_FAMILY_CARDINALITY_INVALID");r=base("alpha-2");((ArrayNode)r.path("observations")).add(observation(r).deepCopy());minimal(evaluate(r),"BS4_SINGLE_OBSERVATION_REQUIRED_NO_AGGREGATION");}
 @Test void reorderPreservesEventsAndWeight()throws Exception{var r=base("beta-3");var before=evaluate(r);var f=obj(observation(r),"/facts");for(String field:List.of("members","records","parentage")){List<JsonNode> a=new ArrayList<>();f.path(field).forEach(a::add);Collections.reverse(a);f.set(field,M.valueToTree(a));}issue(r);var after=evaluate(r);assertEquals(before.path("nonSegregationEvents"),after.path("nonSegregationEvents"));assertEquals(before.path("eventCount"),after.path("eventCount"));assertEquals(-4,after.path("appliedPoints").asInt());}
 @ParameterizedTest @ValueSource(strings={"evaluationComplete","alternativeDetected","unresolvedFindings","memberId","caseId","mondoId"})
 void labelsCannotOverrideAlternativeFacts(String field)throws Exception{var r=base("alpha-2");var n=obj(observation(r),"/diseaseApplicability/alternativeExplanations/0/investigation");String reason="ALTERNATIVE_EXPLANATION_UNRESOLVED";switch(field){case "evaluationComplete"->n.put(field,false);case "alternativeDetected"->n.put(field,true);case "unresolvedFindings"->n.putArray(field).add("TEST_ONLY unresolved alternative");default->{n.put(field,"OTHER");reason="ALTERNATIVE_INVESTIGATION_BINDING_MISMATCH";}}issue(r);minimal(evaluate(r),"BS4_"+reason);}
 @Test void alternativeAndLedgerRostersRequired()throws Exception{for(String path:List.of("diseaseApplicability/alternativeExplanations","locusAttribution/usedEvidence","locusAttribution/candidates")){var r=base("alpha-2");((ArrayNode)observation(r).at("/"+path)).removeAll();issue(r);minimal(evaluate(r),"BS4_"+(path.endsWith("alternativeExplanations")?"ALTERNATIVE_REVIEW_INCOMPLETE":path.endsWith("usedEvidence")?"USED_EVIDENCE_INCOMPLETE":"SOLE_TARGET_REQUIRED"));}}
 @Test void reliableNegativeReviewCannotBorrowAnotherMemberOrTarget()throws Exception{for(String field:List.of("memberId","sampleId","alleleId","method","coverage","capability","result")){var r=base("alpha-2");obj(observation(r),"/nonSegregationReview/memberReviews/3/negativeTest").put(field,"OTHER");issue(r);minimal(evaluate(r),"BS4_"+(List.of("memberId","sampleId","alleleId","method").contains(field)?"NEGATIVE_TEST_BINDING_MISMATCH":"RELIABLE_DETECTION_UNESTABLISHED"));}}
 @Test void claimsAndUnknownFieldsCannotSetScientificResult()throws Exception{var r=base("alpha-2");obj(observation(r),"/nonSegregationReview").putArray("declaredNonSegregatingMembers").add(r.at("/context/patientContext/patientContextId"));issue(r);minimal(evaluate(r),"BS4_DECLARED_EVENTS_CONFLICT");for(String field:List.of("points","strength","allowBs4")){var root=base("alpha-2");obj(observation(root),"/nonSegregationReview").put(field,"CLAIM");issue(root);assertThrows(IllegalArgumentException.class,()->load(root));}}
 @Test void independentValidityAndConditionalReview()throws Exception{var r=base("alpha-2");obj(observation(r),"/diseaseApplicability").put("validityIndependentOfFamily",false);issue(r);minimal(evaluate(r),"BS4_GENE_DISEASE_VALIDITY_UNESTABLISHED");r=base("alpha-2");((ArrayNode)observation(r).at("/diseaseApplicability/conditions")).addObject().put("memberId","test-child").put("kind","AGE").put("requirement","18").put("patientFact","10").put("conclusion","SATISFIED");issue(r);minimal(evaluate(r),"BS4_CONDITIONAL_APPLICABILITY_OUTSIDE_SCOPE");}
 @Test void componentSourcesCannotResolveFromOtherComponent()throws Exception{var r=base("alpha-2");obj(observation(r),"/nonSegregationReview/memberReviews/3").putArray("sourceIds").add(observation(r).at("/facts/sources/0/sourceId"));issue(r);minimal(evaluate(r),"BS4_SOURCE_REFERENCE_UNRESOLVED");}
 @Test void pp1AndBs4MaterialsAreNotInterchangeable()throws Exception{var old=Pp1TestMaterials.base("alpha-2");assertThrows(IllegalArgumentException.class,()->load(old));var current=base("alpha-2");assertThrows(IllegalArgumentException.class,()->Pp1TestMaterials.load(current));}

 @ParameterizedTest @ValueSource(strings={"GT","DP","GQ","AD","FT"})
 void eachRawFieldIsRequired(String field)throws Exception{var r=base("alpha-2");var record=obj(observation(r),"/facts/records/3");var names=new ArrayList<>(List.of("GT","DP","GQ","AD","FT"));var values=new ArrayList<>(List.of("0/0","40","60","40,0","PASS"));int index=names.indexOf(field);names.remove(index);values.remove(index);record.put("format",String.join(":",names)).put("rawSample",String.join(":",values));issue(r);minimal(evaluate(r),"BS4_RECORD_"+field+"_REQUIRED");}
 @Test void emptyReviewAndWrongSchemaCannotBorrowPp1()throws Exception{for(String part:PARTS){var r=base("alpha-2");obj(observation(r),"/"+part).putArray("sources");issue(r);minimal(evaluate(r),"BS4_SOURCE_REQUIRED");}var r=base("alpha-2");obj(observation(r),"/nonSegregationReview").put("schemaVersion","pp1-segregation-review-v1");issue(r);assertThrows(IllegalArgumentException.class,()->load(r));}
 @Test void duplicateEmbeddedKeysHaveBs4Prefix()throws Exception{var r=base("alpha-2");var src=obj(observation(r),"/facts/sources/0");String raw="{\"x\":1,\"x\":2}";src.put("rawUtf8",raw).put("rawSha256",raw(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8)));pinsOnly(r);minimal(evaluate(r),"BS4_SOURCE_DOCUMENT_INVALID");}
 @Test void changingObservationCannotEscapeSharedUse()throws Exception{var r=base("alpha-2");var before=evaluate(r);obj(observation(r),"/facts").put("observationId","ANOTHER_OBSERVATION");for(String part:PARTS)obj(observation(r),"/"+part+"/binding").put("observationId","ANOTHER_OBSERVATION");issue(r);var after=evaluate(r);assertEquals(before.path("evidenceGroupId"),after.path("evidenceGroupId"));assertEquals(before.path("nonSegregationEvents"),after.path("nonSegregationEvents"));obj(observation(r),"/locusAttribution/usedEvidence/0").put("status","APPLIED");issue(r);minimal(evaluate(r),"BS4_SHARED_EVIDENCE_OCCUPIED_OR_CONFLICT");}
 @Test void independentContentIdentityExpectations()throws Exception{var r=evaluate(base("alpha-2"));var selection=obj(r,"/policySelection").deepCopy();String selectionId=selection.remove("selectionId").asText();assertEquals("cspec-selection-sha256-"+hash(selection),selectionId);var trace=obj(r,"/evaluation/deterministicTrace").deepCopy();String traceId=trace.remove("traceSha256").asText();assertEquals(hash(trace),traceId);var evaluation=obj(r,"/evaluation").deepCopy();String id=evaluation.remove("evaluationId").asText();evaluation.remove(List.of("conflict","review"));assertEquals("evaluation-sha256-"+hash(evaluation),id);assertTrue(new RuntimeEvidenceV2Adapter(M).savedAtomicIdentityMatches(obj(r,"/evidence")));}
}
